<?php
declare(strict_types=1);require_once __DIR__.'/auth.php';$loggedUser=current_user();$codigo=trim((string)($_GET['carro']??''));$stmt=db()->prepare('SELECT id,codigo,descripcion,ubicacion FROM carros WHERE codigo=? AND activo=1 LIMIT 1');$stmt->execute([$codigo]);$carro=$stmt->fetch();$mantenciones=[];if($carro){$stmt=db()->prepare('SELECT m.*,u.nombre AS trabajador FROM mantenciones m JOIN usuarios u ON u.id=m.usuario_id WHERE m.carro_id=? ORDER BY m.realizada_en DESC,m.id DESC');$stmt->execute([$carro['id']]);$mantenciones=$stmt->fetchAll();}else{http_response_code(404);}
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Historial <?=e($codigo)?> | Metalrubber</title><link rel="stylesheet" href="assets/css/app.css"><link rel="stylesheet" href="assets/css/modules.css"><style>.public-wrap{width:min(900px,100%);margin:auto;padding:35px 20px 60px}.public-brand{height:58px;width:220px;background:var(--yellow);padding:7px 12px;margin-bottom:35px}.public-brand img{width:100%;height:100%;object-fit:contain}.public-hero,.public-item,.public-empty,.public-notfound{background:var(--white);padding:25px;border-top:4px solid var(--ink);box-shadow:var(--shadow);margin-bottom:17px}.public-hero h1,.public-notfound h1{margin:0 0 9px;font:700 clamp(2.6rem,6vw,4.6rem)/.9 'Barlow Condensed',sans-serif;text-transform:uppercase}.public-hero p{color:var(--muted)}.public-meta{color:var(--muted);font-size:.85rem}.public-item{border-top-color:var(--yellow)}.public-item h2{margin:0;font:700 1.8rem/.95 'Barlow Condensed',sans-serif;text-transform:uppercase}.public-photo{max-width:210px;max-height:210px;object-fit:cover;margin-top:12px;cursor:zoom-in}.public-notfound{border-top-color:var(--red)}.public-notfound strong{color:var(--red)}.public-actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:15px}.public-actions a,.public-actions button{padding:9px 13px;border:1px solid var(--ink);border-radius:2px;background:#fff;color:var(--ink);text-decoration:none;font-weight:800;text-transform:uppercase;font-size:.74rem}.public-actions button{color:var(--red);border-color:#e0aaaa}@media(max-width:600px){.public-wrap{padding:22px 15px 40px}.public-brand{width:190px}}</style></head><body><main class="public-wrap"><div class="public-brand"><img src="assets/brand/logo-metalrubber.png" alt="Metalrubber"></div><?php if(!$carro): ?><section class="public-notfound"><h1>Carro no encontrado</h1><p>El código <strong><?=e($codigo)?></strong> no existe o está inactivo.</p></section><?php else: ?><section class="public-hero"><h1>Historial del carro <?=e($carro['codigo'])?></h1><?php if($carro['descripcion']): ?><p><?=e($carro['descripcion'])?></p><?php endif;?><?php if($carro['ubicacion']): ?><p class="public-meta">Ubicación: <?=e($carro['ubicacion'])?></p><?php endif;?><p class="public-meta"><?=count($mantenciones)?> mantención(es) registrada(s)</p></section><?php if(!$mantenciones): ?><section class="public-empty">Todavía no hay mantenciones registradas para este carro.</section><?php else: foreach($mantenciones as $m): ?><article class="public-item"><h2><?=e($m['tipo'])?></h2><p class="public-meta"><?=e(date('d/m/Y H:i',strtotime($m['realizada_en'])))?> · <?=e($m['trabajador'])?></p><p><?=nl2br(e($m['descripcion']))?></p><?php if($m['foto']&&preg_match('/^[a-f0-9]{40}\.(jpg|png|webp)$/',$m['foto'])): ?><a href="uploads/<?=e($m['foto'])?>" target="_blank" rel="noopener"><img class="public-photo" src="uploads/<?=e($m['foto'])?>" alt="Foto de la mantención"></a><?php endif;?><?php if($loggedUser&&$loggedUser['rol']==='supervisor'): ?><div class="public-actions"><a href="editar_mantencion.php?id=<?=$m['id']?>">Editar</a><form method="post" action="eliminar_mantencion.php" onsubmit="return confirm('¿Eliminar esta mantención definitivamente?');"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$m['id']?>"><button type="submit">Eliminar</button></form></div><?php endif;?></article><?php endforeach;endif;endif;?></main></body></html>
